package raft

import (
	"fmt"
	"testing"

	pb "github.com/lni/dragonboat/v3/raftpb"
)

func TestAssuranceReadIndexDiscardedOnStepDown(t *testing.T) {
	r := newTestRaft(1, []uint64{1, 2, 3}, 10, 1, NewTestLogDB())
	r.becomeCandidate()
	r.becomeLeader()
	r.remotes[2].match = r.log.lastIndex()
	committed := r.tryCommit()
	atTerm := r.hasCommittedEntryAtCurrentTerm()
	r.Handle(pb.Message{From: 1, To: 1, Type: pb.ReadIndex, Hint: 4242, HintHigh: 77})
	registered := r.readIndex.hasPendingRequest()
	fmt.Printf("CA_EVENT {\"event\":\"registered\",\"node\":1,\"committed\":%t,\"at_term\":%t,\"registered\":%t}\n", committed, atTerm, registered)
	r.Handle(pb.Message{From: 1, To: 1, Type: pb.CheckQuorum})
	stillLeader := r.isLeader()
	dropped := len(r.droppedReadIndexes)
	pending := r.readIndex.hasPendingRequest()
	fmt.Printf("CA_EVENT {\"event\":\"step_down\",\"node\":1,\"still_leader\":%t,\"dropped\":%d,\"pending\":%t}\n", stillLeader, dropped, pending)
	before := len(r.readyToRead)
	r.Handle(pb.Message{From: 2, To: 1, Term: r.term, Type: pb.HeartbeatResp, Hint: 4242, HintHigh: 77})
	added := len(r.readyToRead) - before
	fmt.Printf("CA_EVENT {\"event\":\"stale_resp\",\"node\":1,\"ready_added\":%d}\n", added)
	if stillLeader {
		t.Fatalf("leader did not step down")
	}
	if dropped != 0 {
		t.Fatalf("step down reported dropped read contexts: %d", dropped)
	}
	if pending {
		t.Fatalf("read context survived step down")
	}
	if added != 0 {
		t.Fatalf("stale response added ready to read entries: %d", added)
	}
}

package dragonboat

import (
	"fmt"
	"sync"
	"testing"
)

// TestAssuranceReadIndexDeadlineTimeout exercises the node-layer completion of a
// read request whose context was never indexed: the request is registered in a
// read batch with no ready-to-read index, the logical clock passes the caller
// deadline, and an event-loop iteration calls applied.
func TestAssuranceReadIndexDeadlineTimeout(t *testing.T) {
	pool := &sync.Pool{New: func() interface{} { return &RequestState{} }}
	q := newReadIndexQueue(16)
	p := newPendingReadIndex(pool, q)
	req, err := p.read(5)
	if err != nil {
		t.Fatalf("read registration failed: %v", err)
	}
	reqs := q.get()
	if len(reqs) != 1 {
		t.Fatalf("unexpected read queue size: %d", len(reqs))
	}
	ctx := p.nextCtx()
	p.add(ctx, reqs)
	p.tick(6)
	p.applied(0)
	select {
	case r := <-req.CompletedC:
		fmt.Printf("CA_EVENT {\"event\":\"result\",\"code\":\"%s\"}\n", r.code)
		if r.code != requestTimeout {
			t.Fatalf("expected timeout, got %s", r.code)
		}
	default:
		fmt.Printf("CA_EVENT {\"event\":\"result\",\"code\":\"none\"}\n")
		t.Fatalf("no terminal result delivered")
	}
}

package rsm

import (
	"fmt"
	"testing"

	pb "github.com/lni/dragonboat/v3/raftpb"
)

// TestAssuranceMembershipEligibilityMatrix probes the membership acceptance
// rules. Ordered config changes require ConfigChangeId to equal the id of the
// last accepted change, which starts at zero and becomes the accepted entry
// index, so the harness tracks it.
func TestAssuranceMembershipEligibilityMatrix(t *testing.T) {
	m := newMembership(1, 1, true)
	last := uint64(0)
	var index uint64
	step := func(name string, cc pb.ConfigChange) {
		index++
		cc.ConfigChangeId = last
		accepted := m.handleConfigChange(cc, index)
		if accepted {
			last = index
		}
		fmt.Printf("CA_EVENT {\"event\":\"cc\",\"case\":%q,\"accepted\":%t,\"ccid\":%d,\"index\":%d}\n",
			name, accepted, cc.ConfigChangeId, index)
	}
	step("add-node-a", pb.ConfigChange{Type: pb.AddNode, NodeID: 2, Address: "a"})
	step("add-node-a-again", pb.ConfigChange{Type: pb.AddNode, NodeID: 2, Address: "a"})
	step("add-observer-b", pb.ConfigChange{Type: pb.AddObserver, NodeID: 3, Address: "b"})
	step("promote-b-same-addr", pb.ConfigChange{Type: pb.AddNode, NodeID: 3, Address: "b"})
	step("add-observer-c-dup-addr", pb.ConfigChange{Type: pb.AddObserver, NodeID: 4, Address: "b"})
	step("add-witness-w", pb.ConfigChange{Type: pb.AddWitness, NodeID: 5, Address: "w"})
	step("witness-as-observer", pb.ConfigChange{Type: pb.AddObserver, NodeID: 5, Address: "w"})
	step("witness-as-node", pb.ConfigChange{Type: pb.AddNode, NodeID: 5, Address: "w"})
	step("remove-a", pb.ConfigChange{Type: pb.RemoveNode, NodeID: 2})
	step("readd-removed-a", pb.ConfigChange{Type: pb.AddNode, NodeID: 2, Address: "a"})
	step("remove-b", pb.ConfigChange{Type: pb.RemoveNode, NodeID: 3})
	step("remove-w", pb.ConfigChange{Type: pb.RemoveNode, NodeID: 5})
	step("remove-only-node", pb.ConfigChange{Type: pb.RemoveNode, NodeID: 1})
}

