	}

	_, rok := p.raft.remotes[m.From]
	_, ook := p.raft.observers[m.From]
	_, wok := p.raft.witnesses[m.From]

	if rok || ook || wok || !isResponseMessageType(m.Type) {
		p.raft.Handle(m)
	}

