				cu.LastApplied, l.committed)
		}
		if cu.LastApplied > l.processed {
			plog.Panicf("invalid last applied %d, processed %d",
				cu.LastApplied, l.processed)
		}
		l.inmem.appliedLogTo(cu.LastApplied)
	}
}

func (r *raft) quiescedTick() {
	if !r.quiesce {
		r.quiesce = true
		r.log.inmem.resize()
	}
	r.electionTick++
}

func (r *raft) leaderTick() {
	r.mustBeLeader()
	r.electionTick++
	if r.timeForRateLimitCheck() {
		if r.rl.Enabled() {
			r.rl.Tick()
		}
	}
	timeToAbortLeaderTransfer := r.timeToAbortLeaderTransfer()
	if r.timeForCheckQuorum() {
		r.electionTick = 0
		if r.checkQuorum {
			r.Handle(pb.Message{
				From: r.nodeID,
				Type: pb.CheckQuorum,
			})
		}
	}
	if timeToAbortLeaderTransfer {
		r.abortLeaderTransfer()
	}
	r.heartbeatTick++
	if r.timeForHearbeat() {
		r.heartbeatTick = 0
		r.Handle(pb.Message{
			From: r.nodeID,
			Type: pb.LeaderHeartbeat,
		})
	}
	r.checkPendingSnapshotAck()
}

func (r *raft) checkPendingSnapshotAck() {
	if r.isLeader() && r.snapshotting {
		check := func(m map[uint64]*remote) {
			for from, rp := range m {
				if rp.state == remoteSnapshot {
					if rp.delayed.tick() {
						r.Handle(pb.Message{
							Type:   pb.SnapshotStatus,
							From:   from,
							Reject: rp.delayed.rejected,
							Hint:   0,
						})
						rp.clearSnapshotAck()
					} else {
						r.snapshotting = true
					}
				}
			}
		}
		r.snapshotting = false
		check(r.remotes)
		check(r.observers)
		check(r.witnesses)
	}
}

//
// message handlers used by observer, re-route them to follower handlers
//

func (n *node) tick(tick uint64) {
	if n.p == nil {
		plog.Panicf("raft node is nil")
	}
	n.currentTick++
	n.qs.tick()
	n.mq.Tick()
	if n.qs.quiesced() {
		n.p.QuiescedTick()
	} else {
		n.p.Tick()
	}
	n.pendingSnapshot.tick(tick)
	n.pendingProposals.tick(tick)
	n.pendingReadIndexes.tick(tick)

func (n *node) recordMessage(m pb.Message) {
	if (m.Type == pb.Heartbeat || m.Type == pb.HeartbeatResp) && m.Hint > 0 {
		n.qs.record(pb.ReadIndex)
	} else {
		n.qs.record(m.Type)
	}
}

func (q *quiesceState) threshold() uint64 {
	return q.electionTick * 10
}

func (q *quiesceState) newToQuiesce() bool {
	if !q.quiesced() {
		return false
	}
	return q.currentTick-q.quiescedSince < q.electionTick
}

func (q *quiesceState) justExitedQuiesce() bool {
	if q.quiesced() {
		return false
	}
	return q.currentTick-q.exitQuiesceTick < q.threshold()
}

func (q *quiesceState) tryEnterQuiesce() {

func (m *membership) isDeleteOnlyNode(cc pb.ConfigChange) bool {
	if cc.Type == pb.RemoveNode && len(m.members.Addresses) == 1 {
		_, ok := m.members.Addresses[cc.NodeID]
		return ok
	}
	return false
}

func (m *membership) apply(cc pb.ConfigChange, index uint64) {
	m.members.ConfigChangeId = index
	switch cc.Type {
	case pb.AddNode:
		nodeAddr := cc.Address
		delete(m.members.Observers, cc.NodeID)
		if _, ok := m.members.Witnesses[cc.NodeID]; ok {
			panic("not suppose to reach here")
		}
		m.members.Addresses[cc.NodeID] = nodeAddr
	case pb.AddObserver:
		if _, ok := m.members.Addresses[cc.NodeID]; ok {
			panic("not suppose to reach here")
		}
		m.members.Observers[cc.NodeID] = cc.Address
	case pb.AddWitness:
		if _, ok := m.members.Addresses[cc.NodeID]; ok {
			panic("not suppose to reach here")
		}
		if _, ok := m.members.Observers[cc.NodeID]; ok {
			panic("not suppose to reach here")
		}
		m.members.Witnesses[cc.NodeID] = cc.Address
	case pb.RemoveNode:
		delete(m.members.Addresses, cc.NodeID)
		delete(m.members.Observers, cc.NodeID)
		delete(m.members.Witnesses, cc.NodeID)
		m.members.Removed[cc.NodeID] = true
	default:
		panic("unknown config change type")

func (m *membership) isAddWitnessAsObserver(cc pb.ConfigChange) bool {
	if cc.Type == pb.AddObserver {
		_, ok := m.members.Witnesses[cc.NodeID]
		return ok
	}
	return false
}

func (m *membership) isAddWitnessAsNode(cc pb.ConfigChange) bool {
	if cc.Type == pb.AddNode {
		_, ok := m.members.Witnesses[cc.NodeID]
		return ok
	}
	return false
}

func (m *membership) isAddObserverAsWitness(cc pb.ConfigChange) bool {
	if cc.Type == pb.AddWitness {
		_, ok := m.members.Observers[cc.NodeID]
		return ok
	}
	return false
}

func (m *membership) isUpToDate(cc pb.ConfigChange) bool {
	if !m.ordered || cc.Initialize {
		return true
	}
	if m.members.ConfigChangeId == cc.ConfigChangeId {
		return true
	}
	return false

// RequestDeleteNode is a Raft cluster membership change method for requesting
// the specified node to be removed from the specified Raft cluster. It starts
// an asynchronous request to remove the node from the Raft cluster membership
// list. Application can wait on the ResultC() channel of the returned
// RequestState instance to get notified for the outcome.
//
// It is not guaranteed that deleted node will automatically close itself and
// be removed from its managing NodeHost instance. It is application's
// responsibility to call RemoveCluster on the right NodeHost instance to
// actually have the cluster node removed from its managing NodeHost instance.
//
// Once a node is successfully deleted from a Raft cluster, it will not be
// allowed to be added back to the cluster with the same node identity.
//
// When the raft cluster is created with the OrderedConfigChange config flag
// set as false, the configChangeIndex parameter is ignored. Otherwise, it
// should be set to the most recent Config Change Index value returned by the
// SyncGetClusterMembership method. The requested delete node operation will be
// rejected if other membership change has been applied since that earlier call
// to the SyncGetClusterMembership method.

